prompt '---------- refdata/tlgnr_sap_payment_method.sql ----------'

set define off
set serveroutput on

-------------------------------------------------------------------------------
-- is_different_number
-------------------------------------------------------------------------------
-- compares two numbers.
-- They are identical either if a) both are null, b) they are equal by "="
-- They are different if a) either is null and the other not, b) different by "="
create or replace function is_different_number (
    i_a in number,
    i_b in number)
  return number is
begin
  if ((i_a != i_b)
    or (i_a is null and i_b is not null)
    or (i_a is not null and i_b is null)) then
      return 1;
  end if;
  return 0;
end;
/
show errors;

-------------------------------------------------------------------------------
-- is_different_varchar2
-------------------------------------------------------------------------------
-- compares two varchars.
-- They are identical either if a) both are null, b) they are equal by "="
-- They are different if a) either is null and the other not, b) different by "="
create or replace function is_different_varchar2 (
  i_a in varchar2,
  i_b in varchar2)
  return number is
  begin
    if ((i_a != i_b)
        or (i_a is null and i_b is not null)
        or (i_a is not null and i_b is null)) then
      return 1;
    end if;
    return 0;
  end;
/
show errors;

-------------------------------------------------------------------------------
-- tlgnr_sap_payment_method_bs
-------------------------------------------------------------------------------
create or replace
procedure upsert_bs (
  p_sap_payment_method_cd   in varchar2,
  p_ctl_act_cd                in number)
is
  v_table_name    varchar2(48) := 'tlgnr_sap_payment_method_bs';
  v_exists_flag   number;  -- number of existing records of that key (0 or 1)

  begin
    dbms_output.enable(100000);
    dbms_output.put_line('Insert or Update ' || v_table_name || ' (' || p_sap_payment_method_cd || ', ctl_act_cd=' || p_ctl_act_cd || ')');
    select count(bs.sap_payment_method_cd)
    into v_exists_flag
    from tlgnr_sap_payment_method_bs bs
    where bs.sap_payment_method_cd = p_sap_payment_method_cd;

    if (v_exists_flag > 0) then
      if (p_ctl_act_cd != 1) then
        dbms_output.put_line ('NOT updating ' || v_table_name || ' with CD=' || p_sap_payment_method_cd || ', because ctl_act_cd is 0 in loader and data in DB may be better maintained.');      else
        update tlgnr_sap_payment_method_bs set
/* sap_payment_method_cd: cannot update because this is the key */
          ctl_act_cd                     = p_ctl_act_cd,
          ctl_mod_uid                    = 1,
          ctl_mod_ts                     = systimestamp
        where
          sap_payment_method_cd = p_sap_payment_method_cd and
          ctl_act_cd != p_ctl_act_cd  /* not nullable */
        ;
        dbms_output.put_line ('UPDATED if needed: ' || SQL%ROWCOUNT ||'. Existing ' || v_table_name || ' (CD=' || p_sap_payment_method_cd || ').');      end if;
    else
      insert into tlgnr_sap_payment_method_bs (
        sap_payment_method_cd,
        ctl_act_cd,
        ctl_cre_uid, ctl_cre_ts, ctl_mod_uid, ctl_mod_ts
      ) values (
        p_sap_payment_method_cd,
        p_ctl_act_cd,
        1, systimestamp, 1, systimestamp
      );
      dbms_output.put_line ('INSERTED ' || SQL%ROWCOUNT ||' ' || v_table_name || ' (CD=' || p_sap_payment_method_cd || ').');    end if;

  end upsert_bs;
/
show errors;

-------------------------------------------------------------------------------
-- tlgnr_sap_payment_method_tx
-------------------------------------------------------------------------------
create or replace
procedure upsert_tx (
  p_sap_payment_method_cd in varchar2,
  p_lang_cd                 in varchar2,
  p_text                    in varchar2)
is
  v_table_name      varchar2(48) := 'tlgnr_sap_payment_method_tx';
  v_exists_flag     number;        -- number of existing records of that key (0 or 1)
  v_exists_bs_flag  number;        -- number of existing BASE records

  begin
    dbms_output.enable(100000);
    dbms_output.put_line('Insert or Update ' || v_table_name || ' with (' || p_sap_payment_method_cd || ', ' || p_lang_cd || ', ''' || p_text || ''')');
----------------------------------------------------------------------------
-- Lookup BS entry first
----------------------------------------------------------------------------
    select count(bs.sap_payment_method_cd) into v_exists_bs_flag
    from tlgnr_sap_payment_method_bs bs
    where bs.sap_payment_method_cd = p_sap_payment_method_cd;

    if (v_exists_bs_flag > 0) then
      select count(tx.sap_payment_method_cd) into v_exists_flag
      from tlgnr_sap_payment_method_tx tx
      where tx.sap_payment_method_cd = p_sap_payment_method_cd and tx.lang_cd = p_lang_cd;

      if (v_exists_flag > 0) then
        update tlgnr_sap_payment_method_tx set
/* p_sap_payment_method_cd and lang_cd: cannot update because these are the keys */
          txt                            = p_text,
          ctl_mod_uid                    = 1,
          ctl_mod_ts                     = systimestamp
        where
          sap_payment_method_cd = p_sap_payment_method_cd and
          lang_cd = p_lang_cd         and
          1 = is_different_varchar2(txt, p_text)
        ;
        dbms_output.put_line ('UPDATED if needed: ' || SQL%ROWCOUNT ||'. Existing ' || v_table_name || ' (CD=' || p_sap_payment_method_cd || ', LANG=' || p_lang_cd || ').');
      else
        insert into tlgnr_sap_payment_method_tx (
          sap_payment_method_cd,
          lang_cd,
          txt,
          ctl_cre_uid, ctl_cre_ts, ctl_mod_uid, ctl_mod_ts
        ) values (
          p_sap_payment_method_cd,
          p_lang_cd,
          p_text,
          1, systimestamp, 1, systimestamp
        );
        dbms_output.put_line ('INSERTED ' || SQL%ROWCOUNT ||' ' || v_table_name || ' (CD=' || p_sap_payment_method_cd || ', LANG=' || p_lang_cd || ').');      end if;
    else
      dbms_output.put_line ('ERROR: Missing entry in ' || v_table_name || ' (CD=' || p_sap_payment_method_cd || ').');    end if;

  end upsert_tx;
/
show errors;

